INSERT INTO feature VALUES('census','workflow','The bootstrap census','bootstrap','implemented','ordinary',NULL,'`report:bootstrap-census` measures each library for the first rewrite in gandr, by its public items, boundary types, specifications per item, hotpath, dependency depth and size, and ranks them in `ledger/census.md`; a weekly workflow reports a stale census on one issue.',NULL,'.config/census ledger/census.md',NULL,NULL);
